// D:\PythonProject3\src\components\LudoBoard.jsx
import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import { useNavigate } from "react-router-dom";

export default function LudoBoard() {
  const [boardState, setBoardState] = useState(null);
  const [status, setStatus] = useState("⌛ গেম লোড হচ্ছে...");
  const [feeDeducted, setFeeDeducted] = useState(false);
  const [playerDiceCount, setPlayerDiceCount] = useState({ p1: 0, p2: 0 });
  const [winner, setWinner] = useState(null);
  const [timer, setTimer] = useState(60);

  const stompClientRef = useRef(null);
  const timerRef = useRef(null);
  const navigate = useNavigate();

  const token = localStorage.getItem("authToken");
  const gameSessionId = localStorage.getItem("currentSessionId");
  const playerId = parseInt(localStorage.getItem("playerId"), 10);
  const myGameId = localStorage.getItem("myGameId");

  // WebSocket কানেকশন
  useEffect(() => {
    if (!gameSessionId || !playerId) return;

    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      debug: () => {},
      onConnect: () => {
        console.log("🟢 Connected to WebSocket");

        // 🎯 ম্যাচ নোটিফিকেশন (Auto Cancel, Opponent Left ইত্যাদি)
        client.subscribe(`/topic/match/${myGameId}`, (msg) => {
          const payload = JSON.parse(msg.body);
          if (payload.status === "CANCELLED") {
            setStatus("❌ ম্যাচ বাতিল হয়েছে (৬০ সেকেন্ড ইনঅ্যাকটিভিটি)");
            clearInterval(timerRef.current);
            setTimeout(() => navigate("/"), 3000);
          }
        });

        // 🎯 গেম স্টেট আপডেট
        client.subscribe(`/topic/game/${gameSessionId}`, (msg) => {
          const state = JSON.parse(msg.body);
          setBoardState(state);
          setStatus(state.isGameOver ? "🏆 গেম শেষ" : "🎮 গেম চলছে");

          if (state.isGameOver) {
            setWinner(state.winnerId);
            clearInterval(timerRef.current);
          }
        });
      },
    });

    client.activate();
    stompClientRef.current = client;

    // 🎯 ৬০ সেকেন্ড কাউন্টডাউন
    timerRef.current = setInterval(() => {
      setTimer((prev) => {
        if (prev <= 1) {
          clearInterval(timerRef.current);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => {
      if (client) client.deactivate();
      clearInterval(timerRef.current);
    };
  }, [gameSessionId, playerId, token, myGameId, navigate]);

  // 🎲 ডাইস রোল
  const rollDice = async () => {
    try {
      const res = await axios.post(
        `http://localhost:8080/api/match/rollDice/${gameSessionId}`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setPlayerDiceCount({
        p1: res.data.player1DiceCount,
        p2: res.data.player2DiceCount,
      });
      setFeeDeducted(res.data.feeDeducted);
    } catch (err) {
      console.error("Roll dice error:", err);
    }
  };

  // 🚪 গেম ছাড়ার বাটন
  const leaveGame = async () => {
    try {
      await axios.post(
        "http://localhost:8080/api/game/leave",
        { gameId: parseInt(gameSessionId), playerId },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      navigate("/");
    } catch (err) {
      console.error("Leave game error:", err);
    }
  };

  return (
    <div className="max-w-2xl mx-auto mt-8 p-6 bg-white rounded-lg shadow-lg">
      <h2 className="text-2xl font-bold text-center mb-4">🎲 Ludo Game</h2>

      <p className="text-center mb-2">{status}</p>
      {timer > 0 && !boardState?.isGameOver && (
        <p className="text-center text-red-500">⏳ {timer} সেকেন্ডের মধ্যে চাল দিন</p>
      )}

      <div className="flex justify-center my-4">
        <button
          onClick={rollDice}
          disabled={boardState?.isGameOver}
          className="bg-green-600 text-white px-6 py-2 rounded hover:bg-green-700"
        >
          🎲 Roll Dice
        </button>
      </div>

      <div className="text-center">
        <p>Player 1 Dice: {playerDiceCount.p1}</p>
        <p>Player 2 Dice: {playerDiceCount.p2}</p>
        {feeDeducted && <p className="text-green-600">✅ Entry fee deducted</p>}
      </div>

      {winner && (
        <div className="mt-4 text-center text-xl font-bold text-indigo-700">
          🏆 Winner: Player {winner}
        </div>
      )}

      <div className="mt-4 text-center">
        <button
          onClick={leaveGame}
          className="bg-red-500 text-white px-6 py-2 rounded hover:bg-red-600"
        >
          🚪 Leave Game
        </button>
      </div>
    </div>
  );
}
